import { type GeneratedFileIconTheme, getFileIcon } from "@stylicious/core";
import {
	createContext,
	type HTMLAttributes,
	useContext,
	useEffect,
	useState,
} from "react";

export interface FileIconProps {
	theme?: GeneratedFileIconTheme;
	path: string;
	language?: string;
	directory?: boolean;
	expanded?: boolean;
}

export const FileIconTheme = createContext<GeneratedFileIconTheme | null>(null);

export function FileIcon({
	theme,
	path,
	language,
	directory,
	expanded,
	...props
}: FileIconProps & HTMLAttributes<HTMLDivElement>) {
	const contextTheme = useContext(FileIconTheme);

	if (!theme) {
		if (!contextTheme) throw new Error("Theme not passed or found in context");
		theme = contextTheme;
	}

	const icon = getFileIcon({ theme, path, language, directory, expanded });
	const [iconSvg, setIconSvg] = useState<string | null>(null);

	useEffect(() => {
		if (!icon) return;
		theme.svg(icon).then((svg) => setIconSvg(svg));
	}, [icon, theme]);

	if (!iconSvg) return null;
	return <div {...props} dangerouslySetInnerHTML={{ __html: iconSvg }} />;
}
